{
  "tasks": [
    {
      "task_id": "T01",
      "title": "已完成任务的项目分布统计与排序",
      "business_question": "按项目统计已完成任务的数量，并按数量降序排列。注意：仅分析状态为“已完成”的任务。",
      "priority": "P0",
      "priority_reason": "直接回答核心业务目标（按项目统计已完成任务数量并排序），满足所有核心需求 C01-C04。删除此任务将无法提供所需的决策支持数据。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0002",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "completed_task_count"
              }
            ],
            "dimensions": [
              "field_0001"
            ]
          }
        },
        {
          "step_id": "S03",
          "operation": "sort",
          "params": {
            "field": "completed_task_count",
            "direction": "desc"
          }
        }
      ]
    }
  ]
}
